import{_ as e,c as r,o as i,af as h}from"./chunks/framework.BKeRpnBD.js";const _=JSON.parse('{"title":"37、【家人】 離下巽上","description":"橫渠易說 - 37、【家人】 離下巽上","frontmatter":{"title":"37、【家人】 離下巽上","description":"橫渠易說 - 37、【家人】 離下巽上"},"headers":[],"relativePath":"classics/hengqu/039.md","filePath":"classics/hengqu/039.md"}'),l={name:"classics/hengqu/039.md"};function t(n,a,s,d,c,o){return i(),r("div",null,[...a[0]||(a[0]=[h('<h1 id="_37、【家人】-離下巽上" tabindex="-1">37、【家人】 離下巽上 <a class="header-anchor" href="#_37、【家人】-離下巽上" aria-label="Permalink to “37、【家人】 離下巽上”">​</a></h1><h3 id="彖曰-家人-女正位乎內-男正位乎外-男女正-天地之大義也。家人有嚴君焉-父母之謂也。父父-子子-兄兄-弟弟-夫夫-婦婦-而家道正-正家而天下定矣。" tabindex="-1">彖曰：家人，女正位乎內，男正位乎外，男女正，天地之大義也。家人有嚴君焉，父母之謂也。父父，子子，兄兄，弟弟，夫夫，婦婦，而家道正，正家而天下定矣。 <a class="header-anchor" href="#彖曰-家人-女正位乎內-男正位乎外-男女正-天地之大義也。家人有嚴君焉-父母之謂也。父父-子子-兄兄-弟弟-夫夫-婦婦-而家道正-正家而天下定矣。" aria-label="Permalink to “彖曰：家人，女正位乎內，男正位乎外，男女正，天地之大義也。家人有嚴君焉，父母之謂也。父父，子子，兄兄，弟弟，夫夫，婦婦，而家道正，正家而天下定矣。”">​</a></h3><h3 id="象曰-風自火出-家人-君子以言有物而行有恆。" tabindex="-1">象曰：風自火出，家人，君子以言有物而行有恆。 <a class="header-anchor" href="#象曰-風自火出-家人-君子以言有物而行有恆。" aria-label="Permalink to “象曰：風自火出，家人，君子以言有物而行有恆。”">​</a></h3><p>家道之始，始諸飲食烹(飫)［飪］，故曰“風自火出”。 家人道在於烹爨，一家之政，樂不樂、平不平皆系乎此。</p><h3 id="初九-閒有家-悔亡。-象曰-閒有家-志未變也。" tabindex="-1">初九，閒有家，悔亡。 象曰：“閒有家”，志未變也。 <a class="header-anchor" href="#初九-閒有家-悔亡。-象曰-閒有家-志未變也。" aria-label="Permalink to “初九，閒有家，悔亡。 象曰：“閒有家”，志未變也。”">​</a></h3><p>男處女下，悔也。</p><h3 id="六二-無攸遂-在中饋-貞吉。-象曰-六二之吉-順以巽也。" tabindex="-1">六二，無攸遂，在中饋，貞吉。 象曰：六二之吉，順以巽也。 <a class="header-anchor" href="#六二-無攸遂-在中饋-貞吉。-象曰-六二之吉-順以巽也。" aria-label="Permalink to “六二，無攸遂，在中饋，貞吉。 象曰：六二之吉，順以巽也。”">​</a></h3><h3 id="九三-家人嗃嗃-悔厲吉。婦子嘻嘻-終吝。-象曰-家人嗃嗃-未失也-婦子嘻嘻-失家節也。" tabindex="-1">九三，家人嗃嗃，悔厲吉。婦子嘻嘻，終吝。 象曰：“家人嗃嗃”，未失也；“婦子嘻嘻”，失家節也。 <a class="header-anchor" href="#九三-家人嗃嗃-悔厲吉。婦子嘻嘻-終吝。-象曰-家人嗃嗃-未失也-婦子嘻嘻-失家節也。" aria-label="Permalink to “九三，家人嗃嗃，悔厲吉。婦子嘻嘻，終吝。 象曰：“家人嗃嗃”，未失也；“婦子嘻嘻”，失家節也。”">​</a></h3><p>位為過中，則履非得宜，與其慢也寧嚴。</p><h3 id="六四-富家-大吉。-象曰-富家大吉-順在位也。" tabindex="-1">六四，富家，大吉。 象曰：“富家大吉”，順在位也。 <a class="header-anchor" href="#六四-富家-大吉。-象曰-富家大吉-順在位也。" aria-label="Permalink to “六四，富家，大吉。 象曰：“富家大吉”，順在位也。”">​</a></h3><p>柔順在位，故能長保其富。</p><h3 id="九五-王假有家-勿恤-吉。-象曰-王假有家-交相愛也。" tabindex="-1">九五，王假有家，勿恤，吉。 象曰：“王假有家”，交相愛也。 <a class="header-anchor" href="#九五-王假有家-勿恤-吉。-象曰-王假有家-交相愛也。" aria-label="Permalink to “九五，王假有家，勿恤，吉。 象曰：“王假有家”，交相愛也。”">​</a></h3><p>有應在二，得男女內外，家道大正，足以化成天下，故王假之。</p><h3 id="上九-有孚威如-終吉。-象曰-威如之吉-反身之謂也。" tabindex="-1">上九，有孚威如，終吉。 象曰：威如之吉，反身之謂也。 <a class="header-anchor" href="#上九-有孚威如-終吉。-象曰-威如之吉-反身之謂也。" aria-label="Permalink to “上九，有孚威如，終吉。 象曰：威如之吉，反身之謂也。”">​</a></h3><p>以陽居尊，故威如，身修而家齊，故終吉。</p>',15)])])}const b=e(l,[["render",t]]);export{_ as __pageData,b as default};
